package ai.xzkj.recruitment.localconnector;

import org.junit.jupiter.api.Test;
import java.time.Instant;import java.util.UUID;
import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

class InboundAiReplyTaskTest{
 @Test void identifiesPersistedResumeReceiptTasks(){Instant now=Instant.parse("2026-09-14T12:00:00Z");InboundAiReplyTask task=new InboundAiReplyTask(UUID.randomUUID(),UUID.randomUUID(),UUID.randomUUID(),"a".repeat(64),"b".repeat(64),"简历附件已发送","[SYSTEM_RESUME_ATTACHMENT_RECEIPT]","RESUME_RECEIPT",UUID.randomUUID(),now);assertThat(task.isResumeReceipt()).isTrue();}
 @Test void modelQualitySkipCanBeRevalidatedButExpectedSilenceRemainsTerminal(){Instant now=Instant.parse("2026-09-12T08:00:00Z");InboundAiReplyTask quality=new InboundAiReplyTask(UUID.randomUUID(),UUID.randomUUID(),UUID.randomUUID(),"a".repeat(64),"b".repeat(64),"薪资多少",now);quality.start(now);quality.complete(new InboundJobReplyService.Decision(false,"SALARY",.9,null,"AI 回复未通过独立意图校验：未覆盖 SALARY"),now.plusSeconds(1));assertThat(quality.isReplayableFailure(now.plusSeconds(2),java.time.Duration.ofMinutes(30))).isTrue();assertThat(quality.requeueWithFreshInput("薪资多少",null,now.plusSeconds(2))).isTrue();assertThat(quality.isReplayableFailure()).isFalse();InboundAiReplyTask silence=new InboundAiReplyTask(UUID.randomUUID(),UUID.randomUUID(),UUID.randomUUID(),"c".repeat(64),"d".repeat(64),"谢谢",now);silence.start(now);silence.complete(new InboundJobReplyService.Decision(false,"SOCIAL_THANKS",.9,null,"正常静默：自然结束"),now.plusSeconds(1));assertThat(silence.isReplayableFailure(now.plusSeconds(60),java.time.Duration.ofMinutes(30))).isFalse();assertThat(silence.isReplayableFailure(now.plusSeconds(1801),java.time.Duration.ofMinutes(30))).isFalse();}
 @Test void expectedSilenceIsNotAnHrReviewFailure(){Instant now=Instant.parse("2026-09-07T05:00:00Z");InboundAiReplyTask task=new InboundAiReplyTask(UUID.randomUUID(),UUID.randomUUID(),UUID.randomUUID(),"a".repeat(64),"b".repeat(64),"好的",now);task.start(now);task.complete(new InboundJobReplyService.Decision(false,"SOCIAL_ACKNOWLEDGEMENT",.96,null,"正常静默：候选人仅确认收到"),now.plusSeconds(1));assertThat(task.getSendStatus()).isEqualTo("SKIPPED");assertThat(task.isExpectedSilence()).isTrue();}
 @Test void normalSilenceNeverEntersAutomaticReplay(){Instant now=Instant.parse("2026-09-07T05:00:00Z");InboundAiReplyTask task=new InboundAiReplyTask(UUID.randomUUID(),UUID.randomUUID(),UUID.randomUUID(),"a".repeat(64),"b".repeat(64),"谢谢",now);task.start(now);task.complete(new InboundJobReplyService.Decision(false,"SOCIAL_THANKS",.96,null,"正常静默：自然结束"),now.plusSeconds(1));assertThat(task.isReplayableFailure(now.plusSeconds(10),java.time.Duration.ofSeconds(10))).isFalse();assertThat(task.isReplayableFailure(now.plusSeconds(11),java.time.Duration.ofSeconds(10))).isFalse();}
 @Test void replaysOnlyActualCancellationsFromLegacyInterviewCoordination(){Instant now=Instant.parse("2026-09-13T12:00:00Z");InboundAiReplyTask cancellation=new InboundAiReplyTask(UUID.randomUUID(),UUID.randomUUID(),UUID.randomUUID(),"a".repeat(64),"b".repeat(64),"非常抱歉，因临时有事，无法按照定时间参加面试。",now);cancellation.start(now);cancellation.complete(new InboundJobReplyService.Decision(false,"INTERVIEW_COORDINATION",.95,null,"疑似正在确认或变更面试时间，已停止自动回复并转 HR 跟进"),now.plusSeconds(1));assertThat(cancellation.isReplayableFailure()).isTrue();InboundAiReplyTask scheduling=new InboundAiReplyTask(UUID.randomUUID(),UUID.randomUUID(),UUID.randomUUID(),"c".repeat(64),"d".repeat(64),"能安排面试吗",now);scheduling.start(now);scheduling.complete(new InboundJobReplyService.Decision(false,"INTERVIEW_COORDINATION",.95,null,"疑似正在确认或变更面试时间，已停止自动回复并转 HR 跟进"),now.plusSeconds(1));assertThat(scheduling.isReplayableFailure()).isFalse();}
 @Test void genericManualReviewInterviewQuestionIsNotAddedToReplayInventory(){Instant now=Instant.parse("2026-09-13T12:00:00Z");InboundAiReplyTask task=new InboundAiReplyTask(UUID.randomUUID(),UUID.randomUUID(),UUID.randomUUID(),"a".repeat(64),"b".repeat(64),"你好，什么时候方便过去面试呢",now);task.start(now);task.complete(new InboundJobReplyService.Decision(false,"OTHER_RECRUITMENT",.8,null,"AI 判断该消息需要人工复核，未自动回复"),now.plusSeconds(1));assertThat(task.isReplayableFailure()).isFalse();}
 @Test void factMismatchAndUncertainIntentDoNotEnterAutomaticReplay(){Instant now=Instant.parse("2026-09-13T12:00:00Z");for(String reason:java.util.List.of("AI 回复未通过岗位事实校验：精确字段未按已审核原文回答","无法可靠判断消息意图，已转人工")){InboundAiReplyTask task=new InboundAiReplyTask(UUID.randomUUID(),UUID.randomUUID(),UUID.randomUUID(),"a".repeat(64),"b".repeat(64),"工资多少",now);task.start(now);task.complete(new InboundJobReplyService.Decision(false,"SALARY",.8,null,reason),now.plusSeconds(1));assertThat(task.isReplayableFailure()).as(reason).isFalse();}}
 @Test void reportsDistinctSilentAndFailureDispositions(){Instant now=Instant.parse("2026-09-13T12:00:00Z");InboundAiReplyTask expected=new InboundAiReplyTask(UUID.randomUUID(),UUID.randomUUID(),UUID.randomUUID(),"a".repeat(64),"b".repeat(64),"谢谢",now);expected.start(now);expected.complete(new InboundJobReplyService.Decision(false,"SOCIAL_THANKS",.9,null,"正常静默：自然结束"),now.plusSeconds(1));assertThat(expected.dispositionCode()).isEqualTo("EXPECTED_SILENCE");InboundAiReplyTask interview=new InboundAiReplyTask(UUID.randomUUID(),UUID.randomUUID(),UUID.randomUUID(),"c".repeat(64),"d".repeat(64),"能约面试吗",now);interview.start(now);interview.complete(new InboundJobReplyService.Decision(false,"INTERVIEW_COORDINATION",.9,null,"交由 HR"),now.plusSeconds(1));assertThat(interview.dispositionCode()).isEqualTo("INTERVIEW_HR");InboundAiReplyTask fact=new InboundAiReplyTask(UUID.randomUUID(),UUID.randomUUID(),UUID.randomUUID(),"e".repeat(64),"f".repeat(64),"薪资多少",now);fact.start(now);fact.complete(new InboundJobReplyService.Decision(false,"SALARY",.9,null,"AI 回复未通过岗位事实校验：内容与已审核事实不匹配"),now.plusSeconds(1));assertThat(fact.dispositionCode()).isEqualTo("FACT_UNVERIFIED");InboundAiReplyTask model=new InboundAiReplyTask(UUID.randomUUID(),UUID.randomUUID(),UUID.randomUUID(),"1".repeat(64),"2".repeat(64),"问题",now);model.start(now);model.fail("AI_OUTPUT_INVALID","模型结果无效",now.plusSeconds(1));assertThat(model.dispositionCode()).isEqualTo("MODEL_FAILED_RETRYABLE");}
 @Test void supersededProcessingTaskCannotReturnToReadyAfterModelCompletes(){Instant now=Instant.parse("2026-09-07T05:00:00Z");InboundAiReplyTask task=new InboundAiReplyTask(UUID.randomUUID(),UUID.randomUUID(),UUID.randomUUID(),"a".repeat(64),"b".repeat(64),"旧消息",now);task.start(now.plusSeconds(1));task.supersede("候选人已发送新消息",now.plusSeconds(2));task.complete(new InboundJobReplyService.Decision(true,"GREETING",.95,"旧回复","已校验"),now.plusSeconds(3));assertThat(task.getStatus()).isEqualTo("COMPLETED");assertThat(task.getSendStatus()).isEqualTo("SKIPPED");assertThat(task.decision().replyAllowed()).isFalse();assertThat(task.getReplyContent()).isNull();}
 @Test void retainsCandidateTextAfterCompletionAndKeepsDecision(){Instant now=Instant.parse("2026-09-07T05:00:00Z");InboundAiReplyTask task=new InboundAiReplyTask(UUID.randomUUID(),UUID.randomUUID(),UUID.randomUUID(),"a".repeat(64),"b".repeat(64),"候选人的岗位问题",now);task.start(now.plusSeconds(1));task.complete(new InboundJobReplyService.Decision(true,"LOCATION",0.96,"工作地点为广州。","事实校验通过"),now.plusSeconds(2));assertThat(task.getStatus()).isEqualTo("COMPLETED");assertThat(task.getMessageText()).isEqualTo("候选人的岗位问题");assertThat(task.decision().replyAllowed()).isTrue();assertThat(task.decision().category()).isEqualTo("LOCATION");}
 @Test void returnsStaleProcessingTaskToQueue(){Instant now=Instant.parse("2026-09-07T05:00:00Z");InboundAiReplyTask task=new InboundAiReplyTask(UUID.randomUUID(),UUID.randomUUID(),UUID.randomUUID(),"a".repeat(64),"b".repeat(64),"问题",now);task.start(now);task.recoverIfStale(now.plusSeconds(181));assertThat(task.getStatus()).isEqualTo("QUEUED");}
 @Test void rejectsResultFromAnExpiredProcessingAttempt(){Instant now=Instant.parse("2026-09-07T05:00:00Z");InboundAiReplyTask task=new InboundAiReplyTask(UUID.randomUUID(),UUID.randomUUID(),UUID.randomUUID(),"a".repeat(64),"b".repeat(64),"问题",now);String expiredToken=task.start(now);task.recoverIfStale(now.plusSeconds(181));String currentToken=task.start(now.plusSeconds(182));InboundJobReplyService.Decision decision=new InboundJobReplyService.Decision(true,"GREETING",.95,"您好","已校验");assertThat(task.complete(decision,expiredToken,now.plusSeconds(183))).isFalse();assertThat(task.getStatus()).isEqualTo("PROCESSING");assertThat(task.complete(decision,currentToken,now.plusSeconds(184))).isTrue();assertThat(task.getSendStatus()).isEqualTo("READY");}
 @Test void expiresOnlyReadyRepliesOlderThanTheConfiguredCutoff(){Instant now=Instant.parse("2026-09-07T05:00:00Z");InboundAiReplyTask task=new InboundAiReplyTask(UUID.randomUUID(),UUID.randomUUID(),UUID.randomUUID(),"a".repeat(64),"b".repeat(64),"问题",now);task.start(now);task.complete(new InboundJobReplyService.Decision(true,"GREETING",.95,"您好","已校验"),now.plusSeconds(1));assertThat(task.expireReadySend(now,now.plusSeconds(2))).isFalse();assertThat(task.getSendStatus()).isEqualTo("READY");assertThat(task.expireReadySend(now.plusSeconds(2),now.plusSeconds(3))).isTrue();assertThat(task.getSendStatus()).isEqualTo("SKIPPED");assertThat(task.getSendResultReason()).contains("人工处理");}
 @Test void doesNotBypassAttemptLimitWhenTheFinalProcessingAttemptGetsStuck(){Instant now=Instant.parse("2026-09-07T05:00:00Z");InboundAiReplyTask task=new InboundAiReplyTask(UUID.randomUUID(),UUID.randomUUID(),UUID.randomUUID(),"a".repeat(64),"b".repeat(64),"问题",now);for(int attempt=1;attempt<=InboundAiReplyTask.MAX_AI_ATTEMPTS;attempt++){task.start(now.plusSeconds(attempt));if(attempt<InboundAiReplyTask.MAX_AI_ATTEMPTS){assertThat(task.retry("TIMEOUT","超时",now.plusSeconds(attempt))).isTrue();task.releaseRetry(task.getNextAttemptAt());}}assertThat(task.getAttemptCount()).isEqualTo(InboundAiReplyTask.MAX_AI_ATTEMPTS);assertThat(task.recoverIfStale(now.plusSeconds(1_000))).isTrue();assertThat(task.getStatus()).isEqualTo("FAILED");assertThat(task.getLastErrorCode()).isEqualTo("INBOUND_REPLY_AI_STALE_PROCESSING");assertThat(task.getAttemptCount()).isEqualTo(InboundAiReplyTask.MAX_AI_ATTEMPTS);}
 @Test void waitsWithCandidateTextUntilRetryIsDue(){Instant now=Instant.parse("2026-09-07T05:00:00Z");InboundAiReplyTask task=new InboundAiReplyTask(UUID.randomUUID(),UUID.randomUUID(),UUID.randomUUID(),"a".repeat(64),"b".repeat(64),"问题",now);task.start(now);assertThat(task.retry("TIMEOUT","超时",now.plusSeconds(1))).isTrue();assertThat(task.getStatus()).isEqualTo("RETRY_WAIT");assertThat(task.getMessageText()).isEqualTo("问题");task.releaseRetry(now.plusSeconds(5));assertThat(task.getStatus()).isEqualTo("RETRY_WAIT");task.releaseRetry(now.plusSeconds(6));assertThat(task.getStatus()).isEqualTo("QUEUED");}
 @Test void stopsAfterThreeAttemptsAndRetainsCandidateText(){Instant now=Instant.parse("2026-09-07T05:00:00Z");InboundAiReplyTask task=new InboundAiReplyTask(UUID.randomUUID(),UUID.randomUUID(),UUID.randomUUID(),"a".repeat(64),"b".repeat(64),"问题",now);for(int attempt=1;attempt<=3;attempt++){task.start(now.plusSeconds(attempt));boolean retrying=task.retry("TIMEOUT","第 "+attempt+" 次超时",now.plusSeconds(attempt));if(attempt<3){assertThat(retrying).isTrue();task.releaseRetry(task.getNextAttemptAt());}else assertThat(retrying).isFalse();}assertThat(task.getStatus()).isEqualTo("FAILED");assertThat(task.getMessageText()).isEqualTo("问题");assertThat(task.getAttemptCount()).isEqualTo(3);}
 @Test void nonRetryableFailureRetainsItsErrorCode(){Instant now=Instant.parse("2026-09-07T05:00:00Z");InboundAiReplyTask task=new InboundAiReplyTask(UUID.randomUUID(),UUID.randomUUID(),UUID.randomUUID(),"a".repeat(64),"b".repeat(64),"问题",now);task.start(now.plusSeconds(1));task.fail("INBOUND_REPLY_AI_AUTH_FAILED","上游 HTTP 401：认证失败",now.plusSeconds(2));assertThat(task.getStatus()).isEqualTo("FAILED");assertThat(task.getLastErrorCode()).isEqualTo("INBOUND_REPLY_AI_AUTH_FAILED");assertThat(task.getSendStatus()).isEqualTo("SKIPPED");}
 @Test void safelyRequeuesOnlyOnceWithFreshText(){Instant now=Instant.parse("2026-09-07T05:00:00Z");InboundAiReplyTask task=new InboundAiReplyTask(UUID.randomUUID(),UUID.randomUUID(),UUID.randomUUID(),"a".repeat(64),"b".repeat(64),"旧消息",now);task.start(now.plusSeconds(1));task.fail("INBOUND_REPLY_AI_REQUEST_FAILED","上游认证失败",now.plusSeconds(2));assertThat(task.requeueWithFreshInput("当前最新消息","候选人：您好",now.plusSeconds(3))).isTrue();assertThat(task.getStatus()).isEqualTo("QUEUED");assertThat(task.getSendStatus()).isEqualTo("PENDING");assertThat(task.getMessageText()).isEqualTo("当前最新消息");assertThat(task.getConversationContext()).isEqualTo("候选人：您好");assertThat(task.getAttemptCount()).isZero();assertThat(task.getSafeReplayCount()).isEqualTo(1);assertThat(task.getLastErrorCode()).isNull();assertThat(task.getCompletedAt()).isNull();task.start(now.plusSeconds(4));task.fail("AI_OUTPUT_INVALID","仍不合规",now.plusSeconds(5));assertThat(task.requeueWithFreshInput("当前最新消息",null,now.plusSeconds(6))).isFalse();}
 @Test void refusesReplayWhenFailureIsNotRetryableOrInputIsBlank(){Instant now=Instant.parse("2026-09-07T05:00:00Z");InboundAiReplyTask auth=new InboundAiReplyTask(UUID.randomUUID(),UUID.randomUUID(),UUID.randomUUID(),"a".repeat(64),"b".repeat(64),"问题",now);auth.start(now);auth.fail("INBOUND_REPLY_AI_AUTH_FAILED","认证失败",now.plusSeconds(1));assertThat(auth.requeueWithFreshInput("新消息",null,now.plusSeconds(2))).isFalse();assertThat(auth.getStatus()).isEqualTo("FAILED");InboundAiReplyTask invalid=new InboundAiReplyTask(UUID.randomUUID(),UUID.randomUUID(),UUID.randomUUID(),"a".repeat(64),"b".repeat(64),"问题",now);invalid.start(now);invalid.fail("AI_OUTPUT_INVALID","输出不合规",now.plusSeconds(1));assertThat(invalid.requeueWithFreshInput(" ",null,now.plusSeconds(2))).isFalse();assertThat(invalid.getStatus()).isEqualTo("FAILED");}
 @Test void sendLeaseCanOnlyBeClaimedAndCompletedOnce(){Instant now=Instant.parse("2026-09-07T05:00:00Z");UUID device=UUID.randomUUID();InboundAiReplyTask task=new InboundAiReplyTask(UUID.randomUUID(),UUID.randomUUID(),UUID.randomUUID(),"a".repeat(64),"b".repeat(64),"问题",now);task.start(now);task.complete(new InboundJobReplyService.Decision(true,"LOCATION",.98,"工作地点为广州。","已校验"),now.plusSeconds(1));assertThat(task.getSendStatus()).isEqualTo("READY");assertThat(task.claimSend(device,"c".repeat(64),"d".repeat(64),now.plusSeconds(2))).isTrue();assertThat(task.claimSend(device,"e".repeat(64),"f".repeat(64),now.plusSeconds(3))).isFalse();assertThat(task.receiptSend(device,"SUCCEEDED","d".repeat(64),"e".repeat(64),"f".repeat(64),"已确认",now.plusSeconds(4))).isTrue();assertThat(task.receiptSend(device,"SUCCEEDED","d".repeat(64),"e".repeat(64),"f".repeat(64),"已确认",now.plusSeconds(5))).isFalse();assertThat(task.getSendStatus()).isEqualTo("SUCCEEDED");assertThatThrownBy(()->task.receiptSend(device,"UNKNOWN","d".repeat(64),"a".repeat(64),"b".repeat(64),"冲突",now.plusSeconds(6))).isInstanceOf(IllegalStateException.class);}
 @Test void expiredSendLeaseBecomesUnknownAndCannotBeRetried(){Instant now=Instant.parse("2026-09-07T05:00:00Z");InboundAiReplyTask task=new InboundAiReplyTask(UUID.randomUUID(),UUID.randomUUID(),UUID.randomUUID(),"a".repeat(64),"b".repeat(64),"问题",now);task.start(now);task.complete(new InboundJobReplyService.Decision(true,"GREETING",.95,"您好，当前岗位正在招聘。","已校验"),now.plusSeconds(1));task.claimSend(UUID.randomUUID(),"c".repeat(64),"d".repeat(64),now.plusSeconds(2));assertThat(task.getSendLeaseUntil()).isEqualTo(now.plusSeconds(2+InboundAiReplyTask.SEND_LEASE_SECONDS));task.expireSendLease(now.plusSeconds(48));assertThat(task.getSendStatus()).isEqualTo("UNKNOWN");assertThat(task.claimSend(UUID.randomUUID(),"e".repeat(64),"f".repeat(64),now.plusSeconds(49))).isFalse();}
 @Test void unknownSendCanOnlyBeReconciledToSuccessWithoutAnotherSend(){Instant now=Instant.parse("2026-09-07T05:00:00Z");UUID device=UUID.randomUUID();InboundAiReplyTask task=new InboundAiReplyTask(UUID.randomUUID(),UUID.randomUUID(),UUID.randomUUID(),"a".repeat(64),"b".repeat(64),"问题",now);task.start(now);task.complete(new InboundJobReplyService.Decision(true,"GREETING",.95,"您好","已校验"),now.plusSeconds(1));task.claimSend(device,"c".repeat(64),"d".repeat(64),now.plusSeconds(2));task.receiptSend(device,"UNKNOWN","d".repeat(64),"e".repeat(64),"f".repeat(64),"页面未确认",now.plusSeconds(3));assertThatThrownBy(()->task.reconcileUnknownSend(UUID.randomUUID(),"a".repeat(64),"b".repeat(64),now.plusSeconds(4))).isInstanceOf(IllegalStateException.class);assertThat(task.getSendStatus()).isEqualTo("UNKNOWN");assertThat(task.reconcileUnknownSend(device,"a".repeat(64),"b".repeat(64),now.plusSeconds(5))).isTrue();assertThat(task.getSendStatus()).isEqualTo("SUCCEEDED");assertThat(task.getQueueLane()).isEqualTo(InboundAiReplyTask.QUEUE_TERMINAL);assertThat(task.claimSend(device,"e".repeat(64),"f".repeat(64),now.plusSeconds(6))).isFalse();assertThat(task.reconcileUnknownSend(device,"a".repeat(64),"b".repeat(64),now.plusSeconds(7))).isFalse();}
 @Test void definiteSendFailureCanBeRevalidatedButUnknownCannot(){Instant now=Instant.parse("2026-09-07T05:00:00Z");UUID device=UUID.randomUUID();InboundAiReplyTask failed=new InboundAiReplyTask(UUID.randomUUID(),UUID.randomUUID(),UUID.randomUUID(),"a".repeat(64),"b".repeat(64),"您好",now);failed.start(now);failed.complete(new InboundJobReplyService.Decision(true,"GREETING",.95,"您好，可以聊聊。","已校验"),now.plusSeconds(1));failed.claimSend(device,"c".repeat(64),"d".repeat(64),now.plusSeconds(2));failed.receiptSend(device,"FAILED","d".repeat(64),"d".repeat(64),"e".repeat(64),"页面明确未发送",now.plusSeconds(3));assertThat(failed.isReplayableFailure()).isTrue();InboundAiReplyTask unknown=new InboundAiReplyTask(UUID.randomUUID(),UUID.randomUUID(),UUID.randomUUID(),"f".repeat(64),"1".repeat(64),"您好",now);unknown.start(now);unknown.complete(new InboundJobReplyService.Decision(true,"GREETING",.95,"您好，可以聊聊。","已校验"),now.plusSeconds(1));unknown.claimSend(device,"2".repeat(64),"3".repeat(64),now.plusSeconds(2));unknown.expireSendLease(now.plusSeconds(48));assertThat(unknown.isReplayableFailure()).isFalse();}
 @Test void marksAValidatedPartialReplyForHrFollowUp(){Instant now=Instant.parse("2026-09-07T05:00:00Z");InboundAiReplyTask task=new InboundAiReplyTask(UUID.randomUUID(),UUID.randomUUID(),UUID.randomUUID(),"a".repeat(64),"b".repeat(64),"问题",now);task.start(now);task.complete(new InboundJobReplyService.Decision(true,"LOCATION",.95,"地点在广州，排班需要招聘人员确认。","已部分回答，仍需 HR 补充：OTHER_RECRUITMENT"),now.plusSeconds(1));assertThat(task.isPartialReply()).isTrue();}
 @Test void openingUnreadConversationDoesNotInvalidateReadyReply(){Instant now=Instant.parse("2026-09-14T10:00:00Z");UUID jobId=UUID.randomUUID();String messageDigest="b".repeat(64);InboundAiReplyTask task=new InboundAiReplyTask(UUID.randomUUID(),UUID.randomUUID(),jobId,"a".repeat(64),messageDigest,"为什么下午上班",now);task.start(now);task.complete(new InboundJobReplyService.Decision(true,"WORK_TIME",1.0,"工作方面的具体情况，面试的时候会详细解答。","固定回复"),now.plusSeconds(1));BrowserUnreadObservation observation=mock(BrowserUnreadObservation.class);when(observation.isUnread()).thenReturn(false);when(observation.getLatestDirection()).thenReturn("INBOUND");when(observation.getLatestMessageDigest()).thenReturn(messageDigest);when(observation.getMatchedJobPositionId()).thenReturn(jobId);assertThat(InboundAiReplyQueueService.readySendInvalidationReason(task,observation)).isNull();}
 @Test void confirmedOutboundMessageInvalidatesReadyReply(){Instant now=Instant.parse("2026-09-14T10:00:00Z");InboundAiReplyTask task=new InboundAiReplyTask(UUID.randomUUID(),UUID.randomUUID(),UUID.randomUUID(),"a".repeat(64),"b".repeat(64),"您好",now);BrowserUnreadObservation observation=mock(BrowserUnreadObservation.class);when(observation.getLatestDirection()).thenReturn("OUTBOUND");assertThat(InboundAiReplyQueueService.readySendInvalidationReason(task,observation)).contains("HR 外发");}
 @Test void unreadBadgeMisclassificationGetsOneAdditionalSafeReplay(){Instant now=Instant.parse("2026-09-14T10:00:00Z");InboundAiReplyTask task=new InboundAiReplyTask(UUID.randomUUID(),UUID.randomUUID(),UUID.randomUUID(),"a".repeat(64),"b".repeat(64),"请问有宿舍吗",now);for(int replay=0;replay<2;replay++){task.start(now.plusSeconds(replay*3L));task.complete(new InboundJobReplyService.Decision(true,"MEALS_LODGING",1.0,"吃住自理","固定回复"),now.plusSeconds(replay*3L+1));task.skipSend("会话已由 HR 处理或已不再处于候选人未读状态，待发送回复已安全作废",now.plusSeconds(replay*3L+2));assertThat(task.wasUnreadBadgeMisclassified()).isTrue();assertThat(task.isReplayableFailure()).isTrue();assertThat(task.requeueWithFreshInput("请问有宿舍吗",null,now.plusSeconds(replay*3L+3))).isTrue();}task.start(now.plusSeconds(7));task.complete(new InboundJobReplyService.Decision(true,"MEALS_LODGING",1.0,"吃住自理","固定回复"),now.plusSeconds(8));task.skipSend("会话已由 HR 处理或已不再处于候选人未读状态，待发送回复已安全作废",now.plusSeconds(9));assertThat(task.isReplayableFailure()).isFalse();}
 @Test void interviewSchedulingNeverReplaysEvenWithLegacyUnreadBadgeFailure(){Instant now=Instant.parse("2026-09-14T10:00:00Z");InboundAiReplyTask task=new InboundAiReplyTask(UUID.randomUUID(),UUID.randomUUID(),UUID.randomUUID(),"a".repeat(64),"b".repeat(64),"什么时候能安排面试",now);task.start(now);task.complete(new InboundJobReplyService.Decision(true,"INTERVIEW_COORDINATION",.9,"您好","旧版本误判"),now.plusSeconds(1));task.skipSend("会话已由 HR 处理或已不再处于候选人未读状态，待发送回复已安全作废",now.plusSeconds(2));assertThat(task.wasUnreadBadgeMisclassified()).isTrue();assertThat(task.isReplayableFailure()).isFalse();assertThat(task.requeueWithFreshInput("什么时候能安排面试",null,now.plusSeconds(3))).isFalse();}
 @Test void shadowEvaluationKeepsCandidateReplyWithoutMakingItSendable(){Instant now=Instant.parse("2026-09-07T05:00:00Z");InboundAiReplyTask task=new InboundAiReplyTask(UUID.randomUUID(),UUID.randomUUID(),UUID.randomUUID(),"a".repeat(64),"b".repeat(64),"工资多少",now);task.start(now);task.complete(new InboundJobReplyService.Decision(true,"SALARY",.97,"薪资范围是 8-13K。","事实校验通过").asShadowEvaluation(),now.plusSeconds(1));assertThat(task.getSendStatus()).isEqualTo("SKIPPED");assertThat(task.isShadowEvaluation()).isTrue();assertThat(task.wasReplyApproved()).isTrue();assertThat(task.getReplyContent()).isEqualTo("薪资范围是 8-13K。");}
 @Test void routesTaskAcrossAnalysisSendAndRevalidationLanes(){Instant now=Instant.parse("2026-09-07T05:00:00Z");UUID device=UUID.randomUUID();InboundAiReplyTask sent=new InboundAiReplyTask(UUID.randomUUID(),UUID.randomUUID(),UUID.randomUUID(),"a".repeat(64),"b".repeat(64),"你好",now);assertThat(sent.getQueueLane()).isEqualTo(InboundAiReplyTask.QUEUE_ANALYSIS);sent.start(now.plusSeconds(1));assertThat(sent.getQueueLane()).isEqualTo(InboundAiReplyTask.QUEUE_ANALYSIS);sent.complete(new InboundJobReplyService.Decision(true,"GREETING",.95,"您好，可以聊聊。","固定模板"),now.plusSeconds(2));assertThat(sent.getQueueLane()).isEqualTo(InboundAiReplyTask.QUEUE_SEND);sent.claimSend(device,"c".repeat(64),"d".repeat(64),now.plusSeconds(3));assertThat(sent.getQueueLane()).isEqualTo(InboundAiReplyTask.QUEUE_SEND);sent.receiptSend(device,"SUCCEEDED","d".repeat(64),"e".repeat(64),"f".repeat(64),"已确认",now.plusSeconds(4));assertThat(sent.getQueueLane()).isEqualTo(InboundAiReplyTask.QUEUE_TERMINAL);InboundAiReplyTask failed=new InboundAiReplyTask(UUID.randomUUID(),UUID.randomUUID(),UUID.randomUUID(),"1".repeat(64),"2".repeat(64),"你好",now);failed.start(now.plusSeconds(1));failed.complete(new InboundJobReplyService.Decision(true,"GREETING",.95,"您好，可以聊聊。","固定模板"),now.plusSeconds(2));failed.claimSend(device,"3".repeat(64),"4".repeat(64),now.plusSeconds(3));failed.receiptSend(device,"FAILED","4".repeat(64),"4".repeat(64),"5".repeat(64),"页面明确未发送",now.plusSeconds(4));assertThat(failed.getQueueLane()).isEqualTo(InboundAiReplyTask.QUEUE_REVALIDATION);}
}
